const [currentData, previousData] = [$('GSC — Son 28 Gün').item.json, $('GSC — Önceki 28 Gün').item.json];
const current = {};
const previous = {};

(currentData.rows || []).forEach(r => { current[r.keys[0]] = r; });
(previousData.rows || []).forEach(r => { previous[r.keys[0]] = r; });

const decaying = [];
const growing = [];

Object.keys(current).forEach(page => {
  const curr = current[page];
  const prev = previous[page];
  if (!prev || prev.clicks === 0) return;
  const clickChange = ((curr.clicks - prev.clicks) / prev.clicks) * 100;
  const posChange = prev.position - curr.position; // pozitif = iyileşme
  if (clickChange < -20) decaying.push({ page: page.replace('https://www.albanexa.com',''), clicks: curr.clicks, prevClicks: prev.clicks, change: clickChange.toFixed(0), pos: curr.position.toFixed(1) });
  if (clickChange > 50 && curr.clicks >= 5) growing.push({ page: page.replace('https://www.albanexa.com',''), clicks: curr.clicks, change: clickChange.toFixed(0) });
});

decaying.sort((a,b) => a.change - b.change);
growing.sort((a,b) => b.change - a.change);

let msg = `📉 *İçerik Performans Raporu — ${new Date().toLocaleDateString('tr-TR')}*\n\n`;
if (decaying.length > 0) {
  msg += `*Düşen Sayfalar (>${20}% tıklama kaybı):*\n`;
  decaying.slice(0,5).forEach(p => { msg += `• ${p.page}\n  ${p.prevClicks}→${p.clicks} tık (${p.change}%) · Konum: ${p.pos}\n`; });
} else {
  msg += `✅ Ciddi düşüş yok.\n`;
}
if (growing.length > 0) {
  msg += `\n*Büyüyen Sayfalar:*\n`;
  growing.slice(0,3).forEach(p => { msg += `• ${p.page} +${p.change}% (${p.clicks} tık)\n`; });
}

return [{ json: { message: msg } }];
